{
  "name": "@jurci/tui-monthly-usage",
  "version": "1.0.4",
  "description": "Opencode TUI plugin for tracking daily, weekly, and monthly token usage and model spend in the sidebar",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/jstibran/tui-monthly-usage-plugin.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "usage",
    "monthly-usage",
    "opentui"
  ],
  "files": [
    "dist"
  ],
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    },
    "./usage": {
      "import": "./dist/usage.js",
      "types": "./dist/usage.d.ts"
    }
  },
  "scripts": {
    "build": "tsc && npx --yes bun@1.3.3 run scripts/build-tui.ts",
    "typecheck": "tsc --noEmit",
    "test": "npm run build && node --test test/plugin.test.mjs && npm run test:tui",
    "test:tui": "npx --yes bun@1.3.3 test --preload @opentui/solid/preload ./test/tui.test.mjs",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run clean && npm run build"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/theme": "^2.0.27",
    "@opentui/core": "^0.6.1",
    "@opentui/solid": "^0.6.1",
    "@types/node": "^26.4.0",
    "solid-js": "1.9.12",
    "typescript": "^7.0.2"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.27"
  }
}
